import{_ as t,o as r,c as e,a2 as a}from"./chunks/framework.CnHmQiA8.js";const u=JSON.parse('{"title":"编辑与排版","description":"","frontmatter":{"title":"编辑与排版","outline":[2,3]},"headers":[],"relativePath":"guide/editing.md","filePath":"guide/editing.md","lastUpdated":1795437342000}'),l={name:"guide/editing.md"};function n(i,o,s,d,c,g){return r(),e("div",null,[...o[0]||(o[0]=[a('<h1 id="编辑与排版" tabindex="-1">编辑与排版 <a class="header-anchor" href="#编辑与排版" aria-label="Permalink to &quot;编辑与排版&quot;">​</a></h1><p>在编辑界面中，所有改动都可以随时通过顶栏 <code>↶</code> <code>↷</code> 或 <code>Ctrl+Z</code> / <code>Ctrl+Y</code>（或 <code>Ctrl+Shift+Z</code>）撤销与重做，最多支持 <strong>200 步</strong>（同一处连续打字合并为一步）。</p><h2 id="_1-题目与综合题" tabindex="-1">1. 题目与综合题 <a class="header-anchor" href="#_1-题目与综合题" aria-label="Permalink to &quot;1. 题目与综合题&quot;">​</a></h2><h3 id="难度、变式题与题目可选项" tabindex="-1">难度、变式题与题目可选项 <a class="header-anchor" href="#难度、变式题与题目可选项" aria-label="Permalink to &quot;难度、变式题与题目可选项&quot;">​</a></h3><ul><li><strong>难度等级</strong>：物理预设默认分 <code>A ★ 简单</code>、<code>B ★★ 中等</code>、<code>C ★★★ 难</code>（数学教学案分 <code>A～E</code> 五级），可在大纲顶部的 <strong>版式设置 → 难度显示</strong> 选择显示样式或隐藏。</li><li><strong>变式题</strong>：在题目属性面板勾选 <strong>变式题</strong>，题号自动编为 <code>a. b. c.</code> 紧跟在上一道题之后，不占用数字题号（如 <code>1. a. b. 2. …</code>）。导出 Word 时数字题号仍保持自动编号。</li><li><strong>重点题与审题</strong>（所有题型均支持）： <ul><li>在属性面板 <strong>仅教师版</strong> 页勾选 <strong>重点题</strong>，教师版题干前会显示红色加粗的 <code>【重点题】</code>；</li><li>填写 <strong>审题</strong> 内容后，教师版会将其排在解析之前，开头显示 <code>【审题】</code>。</li><li>数学教学案默认开启这两项，其他预设可在 <strong>版式设置 → 题目可选项</strong> 中随时按需开启或关闭（关闭后只是暂不显示与排版，已填内容仍会保留）。</li></ul></li></ul><h3 id="综合题与小题整理" tabindex="-1">综合题与小题整理 <a class="header-anchor" href="#综合题与小题整理" aria-label="Permalink to &quot;综合题与小题整理&quot;">​</a></h3><ul><li>综合题由 <strong>标题</strong>（如“材料一”）、可选的 <strong>背景材料与配图</strong> 以及 <strong>若干小题</strong> 组成，小题题号与全卷连续。</li><li><strong>答案与解析排布</strong>：可在综合题属性面板或右键快捷窗口中切换“集中在最后”或“分到各小题”，系统按题号自动拆开或合并（可撤销）。</li><li><strong>小题跨综合题移动</strong>：把小题上移到第一道之前、或下移到最后一道之后即可移出综合题；独立题目紧挨着综合题时上/下移即可并入；也可以通过右键快捷窗口的 <strong>移到</strong> 或直接在大纲中拖动。</li></ul><h3 id="作业单与分页重新编号" tabindex="-1">作业单与分页重新编号 <a class="header-anchor" href="#作业单与分页重新编号" aria-label="Permalink to &quot;作业单与分页重新编号&quot;">​</a></h3><ul><li>通过 <strong>添加</strong> 菜单中的预制模块插入 <strong>作业单</strong>，会自动从新的一页开始，生成大标题与“姓名 / 教室 / 正确率”栏，其后的题目自动从 <code>1</code> 重新编号。</li><li>大标题、栏目标题与题型分组也可在各自属性面板的 <strong>版式</strong> 中单独勾选 <strong>从新的一页开始</strong> 与 <strong>之后的题号从 1 重新开始</strong>。</li></ul><h2 id="_2-知识点、挖空重点与表格" tabindex="-1">2. 知识点、挖空重点与表格 <a class="header-anchor" href="#_2-知识点、挖空重点与表格" aria-label="Permalink to &quot;2. 知识点、挖空重点与表格&quot;">​</a></h2><h3 id="知识点与-重点-标记" tabindex="-1">知识点与“重点”标记 <a class="header-anchor" href="#知识点与-重点-标记" aria-label="Permalink to &quot;知识点与“重点”标记&quot;">​</a></h3><ul><li>知识梳理按“一、二、三……”分组为知识点（包含标题、正文段落与插图），支持设置留白、跨页与换页；单个段落也可设置段后空行、从此段换页或从某段拆分为新知识点。</li><li>编辑知识点时，点击格式工具栏最前面的 <strong>重点</strong> 按钮，可将选中的文字或公式设为红色加粗下划线（再点一次取消）。在 <strong>物理知识点手册</strong> 预设中，学生版会自动将这些标了重点的内容挖空为下划线横线，方便课堂默写。</li></ul><h3 id="表格编辑" tabindex="-1">表格编辑 <a class="header-anchor" href="#表格编辑" aria-label="Permalink to &quot;表格编辑&quot;">​</a></h3><ul><li>在输入框下方点击 <strong>插入表格</strong> 新建，或点击 <strong>编辑表格</strong> 进入表格编辑器（输入框内显示为 <code>⟦表格N⟧</code>，删掉它即删除表格）。</li><li>支持插入/删除行列、按住 <code>Shift</code> 连选多个单元格后 <strong>合并单元格</strong>、光标置于合并格内 <strong>拆分单元格</strong>、按厘米设置列宽或 <strong>平均分布 / 自动</strong>，内部同样支持格式工具（含“重点”）与撤销重做。</li><li>在中间预览区域中，还可以直接拖动表格的竖线调整列宽。</li><li>题型整理预设下可在表格编辑器中勾选“当前单元格在学生版换成书写横线 N 行”，使学生版自动生成虚线书写格。</li></ul><h2 id="_3-文字格式、填空与公式" tabindex="-1">3. 文字格式、填空与公式 <a class="header-anchor" href="#_3-文字格式、填空与公式" aria-label="Permalink to &quot;3. 文字格式、填空与公式&quot;">​</a></h2><ul><li><strong>文字格式</strong>：在属性面板顶部工具栏使用 <code>B / I / U</code>（或 <code>Ctrl+B / I / U</code>）设置加粗、倾斜、下划线，使用 <code>红 / 黑 / 蓝</code> 设置文字颜色（选“黑”恢复默认）。在预览中直接选中文字或公式，上方也会弹出浮动工具条，还可快速设置段落左对齐 / 居中 / 右对齐。</li><li><strong>填空横线</strong>：在编辑框中输入至少 3 个连续下划线（如 <code>____</code>），每 2 个下划线代表 1 个字宽，增减下划线即可直观控制横线长度。</li><li><strong>字体</strong>：各输入框标题旁可单独指定字体（随样式 / 宋体 / 黑体 / 楷体 / 仿宋），预览与导出 Word 一致。</li><li><strong>可视化公式</strong>：点击 <strong>插入公式</strong> 在光标处插入新公式；在预览中直接点击已有公式即可调出可视化编辑面板（附带常用模板按钮与数学键盘）。选中公式标记 <code>⟦公式N⟧</code> 也可为其加粗、加下划线或设颜色。</li><li><strong>公式字母正斜体</strong>：默认采用正体字母（与物理常用规范一致），每份教学案可在 <strong>版式设置 → 公式字母</strong> 中一键切换正体或斜体，也可在首页 <code>设置…</code> 中设置全局默认。从 Word 导入且未做修改的公式在导出时原样保留。</li></ul><h2 id="_4-版式设置、快捷窗口与大纲拖拽" tabindex="-1">4. 版式设置、快捷窗口与大纲拖拽 <a class="header-anchor" href="#_4-版式设置、快捷窗口与大纲拖拽" aria-label="Permalink to &quot;4. 版式设置、快捷窗口与大纲拖拽&quot;">​</a></h2><h3 id="全局与单题版式" tabindex="-1">全局与单题版式 <a class="header-anchor" href="#全局与单题版式" aria-label="Permalink to &quot;全局与单题版式&quot;">​</a></h3><ul><li>点击大纲顶部的 <strong>版式设置</strong>，可分别设定教案与学案是否允许题目跨页（默认教案允许跨页省纸、学案整题同页）、难度显示方式、题目可选项、选项列间距方案（支持自定义修改各列起始字宽并“另存为方案”供全局复用），以及标题 / 题目 / 知识点 / 正文段落的 <strong>行距倍数</strong>。</li><li>单道题目也可以在自身属性面板底部的 <strong>版式</strong> 区域单独覆盖选项排布（每行几项）、题后留白、整题同页、换页以及本题独立的选项位置。</li></ul><h3 id="快捷版式窗口" tabindex="-1">快捷版式窗口 <a class="header-anchor" href="#快捷版式窗口" aria-label="Permalink to &quot;快捷版式窗口&quot;">​</a></h3><p>在中间预览或左侧大纲中 <strong>右键点击</strong> 任意一道题、知识点、综合题或标题，即可弹出快捷版式窗口，直接修改难度、选项排布、整题同页、题后留白、换页、重编题号、综合题答案位置、移动目标以及上移 / 下移（支持连续点击）与删除。</p><h3 id="左侧大纲拖拽排序" tabindex="-1">左侧大纲拖拽排序 <a class="header-anchor" href="#左侧大纲拖拽排序" aria-label="Permalink to &quot;左侧大纲拖拽排序&quot;">​</a></h3><ul><li>在左侧大纲按住某一项约 <code>0.3 秒</code> 即可开始拖动，松手后落入蓝色插入线位置；拖动期间滚动鼠标滚轮可快速翻页，拖到列表上下边缘会自动滚动，按 <code>Esc</code> 取消。</li><li>题目（含综合题内的小题）可拖进或拖出综合题：拖到综合题末尾时，鼠标偏右（插入线缩进）表示放进综合题，偏左表示放在综合题后面。</li></ul>',23)])])}const _=t(l,[["render",n]]);export{u as __pageData,_ as default};
